-- ---------- bitwise XOR: bit32/bit (Delta, Synapse, Fluxus...) + pure-Lua fallback ----------
local _bxor
do
    local ok32, b32 = pcall(function() return bit32 end)
    local ok1, b1 = pcall(function() return bit end)
    if ok32 and b32 and b32.bxor then
        _bxor = b32.bxor
    elseif ok1 and b1 and b1.bxor then
        _bxor = b1.bxor
    else
        local function _pxor(a, b)
            local result, bitval = 0, 1
            while a > 0 or b > 0 do
                local ab, bb = a % 2, b % 2
                if ab ~= bb then result = result + bitval end
                a = (a - ab) / 2
                b = (b - bb) / 2
                bitval = bitval * 2
            end
            return result
        end
        _bxor = _pxor
    end
end

local function _hx(h)
    local t = {}
    for i = 1, #h, 2 do t[#t + 1] = tonumber(h:sub(i, i + 1), 16) end
    return t
end
local _K1, _K2 = _hx(_k1), _hx(_k2)
local _K1N, _K2N = #_K1, #_K2

local function _b64d(s)
    local b = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    s = string.gsub(s, "[^" .. b .. "=]", "")
    local out = {}
    for i = 1, #s, 4 do
        local c1 = (string.find(b, s:sub(i, i), 1, true) or 1) - 1
        local c2 = (string.find(b, s:sub(i + 1, i + 1), 1, true) or 1) - 1
        local c3 = (string.find(b, s:sub(i + 2, i + 2), 1, true) or 1) - 1
        local c4 = (string.find(b, s:sub(i + 3, i + 3), 1, true) or 1) - 1
        local n = c1 * 262144 + c2 * 4096 + c3 * 64 + c4
        local b1 = math.floor(n / 65536) % 256
        local b2 = math.floor(n / 256) % 256
        local b3 = n % 256
        out[#out + 1] = string.char(b1)
        if s:sub(i + 2, i + 2) ~= "=" and s:sub(i + 2, i + 2) ~= "" then out[#out + 1] = string.char(b2) end
        if s:sub(i + 3, i + 3) ~= "=" and s:sub(i + 3, i + 3) ~= "" then out[#out + 1] = string.char(b3) end
    end
    return table.concat(out)
end

